import{_ as a,o as i,c as t,a0 as s}from"./chunks/framework.CBux2OW7.js";const p=JSON.parse('{"title":"Generating News Workflow","description":"","frontmatter":{},"headers":[],"relativePath":"workflows/generating-news.md","filePath":"workflows/generating-news.md"}'),n={name:"workflows/generating-news.md"};function r(o,e,c,l,h,d){return i(),t("div",null,[...e[0]||(e[0]=[s('<h1 id="generating-news-workflow" tabindex="-1">Generating News Workflow <a class="header-anchor" href="#generating-news-workflow" aria-label="Permalink to &quot;Generating News Workflow&quot;">​</a></h1><p>This workflow describes the exact internal lifecycle of an article from raw data to published content. AI agents modifying this codebase must understand this flow to avoid breaking the core CMS functionality.</p><h2 id="_1-trigger" tabindex="-1">1. Trigger <a class="header-anchor" href="#_1-trigger" aria-label="Permalink to &quot;1. Trigger&quot;">​</a></h2><p>The process can be triggered automatically via a CRON job (<code>php artisan schedule:run</code>) or manually via the Dashboard UI (<code>/api/agents/force-synthesize</code>).</p><h2 id="_2-aggregation-selection" tabindex="-1">2. Aggregation &amp; Selection <a class="header-anchor" href="#_2-aggregation-selection" aria-label="Permalink to &quot;2. Aggregation &amp; Selection&quot;">​</a></h2><p>The <code>NewsAgent</code> queries the <code>ScoutedArticle</code> table:</p><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">SELECT</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> *</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> FROM</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> scouted_articles </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">WHERE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> is_processed </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> ORDER BY</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> relevance_score </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">DESC</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> LIMIT</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 5</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span></code></pre></div><h2 id="_3-idea-generation" tabindex="-1">3. Idea Generation <a class="header-anchor" href="#_3-idea-generation" aria-label="Permalink to &quot;3. Idea Generation&quot;">​</a></h2><p>The raw content from these 5 scouted articles is sent to <code>GeminiService-&gt;generateIdeas()</code>.</p><ul><li><strong>Prompt Logic:</strong> &quot;Act as a Senior Editor. Read these 5 articles and synthesize 3 unique editorial angles that combine them.&quot;</li></ul><h2 id="_4-drafting" tabindex="-1">4. Drafting <a class="header-anchor" href="#_4-drafting" aria-label="Permalink to &quot;4. Drafting&quot;">​</a></h2><p>The best idea is passed to <code>GeminiService-&gt;generateDraft()</code>.</p><ul><li><strong>Output Constraint:</strong> Gemini MUST return raw HTML. No Markdown. No JSON wrappers (unless handled by the recursive unwrapping logic).</li></ul><h2 id="_5-persistence-translation" tabindex="-1">5. Persistence &amp; Translation <a class="header-anchor" href="#_5-persistence-translation" aria-label="Permalink to &quot;5. Persistence &amp; Translation&quot;">​</a></h2><p>The raw HTML is stored in <code>Article-&gt;content</code>. When a user requests the article in Spanish (<code>?locale=es</code>), the <code>ArticleController</code> intercepts the request. If the <code>translations</code> JSON column lacks the &#39;es&#39; key, it triggers an on-the-fly translation via <code>GeminiService</code> before rendering.</p><h2 id="_6-fact-checking-async" tabindex="-1">6. Fact-Checking (Async) <a class="header-anchor" href="#_6-fact-checking-async" aria-label="Permalink to &quot;6. Fact-Checking (Async)&quot;">​</a></h2><p>A background Job is dispatched. The <code>FactCheckService</code> extracts claims, searches the web via <code>SourceSearchService</code>, scrapes via <code>JinaReaderService</code>, and assigns a truth score.</p>',17)])])}const k=a(n,[["render",r]]);export{p as __pageData,k as default};
